import * as BABYLON from "@babylonjs/core";

/**
 * BioSpecies — central catalog of 100+ collectible "robotic Pokemon"-style
 * pets. Each species is purely data; visuals are generated by
 * BioCreatureSystem.makeDescriptor() from `archetype` + `elementalType`.
 *
 * NOTE: keep the original five ids (`robofox`, `crystalbeetle`,
 * `hoverserpent`, `neonowl`, `voltfrog`) intact so old saves still resolve.
 */

export type Archetype =
  | "fox" | "cat" | "bunny" | "mouse" | "pup"
  | "beetle" | "frog" | "lizard" | "salamander"
  | "serpent" | "owl" | "bird" | "dragon"
  | "fish" | "crab" | "turtle"
  | "bear" | "monkey" | "golem"
  | "flutter" | "slime";

export type ElementalType =
  | "normal" | "flame" | "water" | "grass" | "electric"
  | "ice" | "psychic" | "evil" | "steel" | "crystal" | "dragon";

export type Rarity = "common" | "uncommon" | "rare" | "legendary";

export interface BioCreatureSpecies {
  id: string;
  name: string;
  archetype: Archetype;
  elementalType: ElementalType;
  rarity: Rarity;
  scale: number;
  baseCaptureChance: number;
  primary: BABYLON.Color3;
  secondary: BABYLON.Color3;
  emissive: BABYLON.Color3;
  /** Short tagline shown in the Bio Garden / Dex. */
  role: string;
}

// ---------------------------------------------------------------- palettes
// Default per-type colors used when a species omits explicit overrides.
const c = (r: number, g: number, b: number) => new BABYLON.Color3(r, g, b);

interface Palette { primary: BABYLON.Color3; secondary: BABYLON.Color3; emissive: BABYLON.Color3; }

