/** UI hex tint per type (used for badges + dex tabs). */
export const TYPE_HEX: Record<ElementalType, string> = {
  normal: "#bdbdc4", flame: "#ff7038", water: "#4f9cff", grass: "#65d24a",
  electric: "#f7d633", ice: "#9ad9f7", psychic: "#f56fb8", evil: "#6b5392",
  steel: "#9aa6b3", crystal: "#7be1ff", dragon: "#a663ff",
};

/** Rarity to a 1-4 weight used by the wild spawn distribution. */
export const RARITY_WEIGHT: Record<Rarity, number> = {
  common: 8, uncommon: 4, rare: 2, legendary: 1,
};

const RARITY_HP: Record<Rarity, number> = { common: 60, uncommon: 75, rare: 95, legendary: 130 };
const RARITY_ATK: Record<Rarity, number> = { common: 10, uncommon: 13, rare: 17, legendary: 24 };
const RARITY_CAP: Record<Rarity, number> = { common: 0.55, uncommon: 0.42, rare: 0.28, legendary: 0.14 };

// --------------------------------------------------------------- compact spec
type SpecArgs = [
  id: string,
  name: string,
  archetype: Archetype,
  type: ElementalType,
  rarity: Rarity,
  scale: number,
  role: string,
  override?: Partial<Palette>,
];

function spec(...a: SpecArgs): BioCreatureSpecies {
  const [id, name, archetype, type, rarity, scale, role, override] = a;
  const pal = TYPE_PALETTES[type];
  return {
    id,
    name,
    archetype,
    elementalType: type,
    rarity,
    scale,
    baseCaptureChance: RARITY_CAP[rarity],
    primary: override?.primary ?? pal.primary,
    secondary: override?.secondary ?? pal.secondary,
    emissive: override?.emissive ?? pal.emissive,
    role,
  };
}

/** Base HP/ATK from rarity — exported for the capture flow. */
export function statsFromRarity(rarity: Rarity): { hp: number; attack: number; speed: number } {
  return { hp: RARITY_HP[rarity], attack: RARITY_ATK[rarity], speed: 1.0 };
}

