// ---------------------------------------------------------------- helpers
export function getSpeciesById(id: string): BioCreatureSpecies | null {
  return BIO_SPECIES.find(s => s.id === id) ?? null;
}

export function speciesByType(type: ElementalType): BioCreatureSpecies[] {
  return BIO_SPECIES.filter(s => s.elementalType === type);
}

export const ALL_TYPES: ElementalType[] = [
  "normal", "flame", "water", "grass", "electric", "ice", "psychic", "evil", "steel", "crystal", "dragon",
];

/** Pick a random species weighted by rarity. */
export function pickWeightedSpecies(rng: () => number = Math.random): BioCreatureSpecies {
  let total = 0;
  for (const s of BIO_SPECIES) total += RARITY_WEIGHT[s.rarity];
  let pick = rng() * total;
  for (const s of BIO_SPECIES) {
    pick -= RARITY_WEIGHT[s.rarity];
    if (pick <= 0) return s;
  }
  return BIO_SPECIES[0];
}
